    {"name": "edit", "arguments": {"path": "src/lib.rs", "old": "    pub fn munge_in_place(&mut self, data: &mut [u8]) {\n        todo!()\n    }", "new": "    pub fn munge_in_place(&mut self, data: &mut [u8]) {\n        if self.key.is_empty() {\n            return;\n        }\n        for byte in data {\n            *byte ^= self.key[self.position % self.key.len()];\n            self.position += 1;\n        }\n    }"}},
    {"name": "edit", "arguments": {"path": "src/lib.rs", "old": "    pub fn munge<Data>(&mut self, data: Data) -> impl Iterator<Item = u8> {\n        todo!();\n        // this empty iterator silences a compiler complaint that\n        // () doesn't implement ExactSizeIterator\n        std::iter::empty()\n    }", "new": "    pub fn munge<Data>(&mut self, data: Data) -> impl Iterator<Item = u8> + '_\n    where\n        Data: IntoIterator,\n        Data::Item: std::borrow::Borrow<u8>,\n    {\n        let key = self.key;\n        let position = &mut self.position;\n        data.into_iter().map(move |byte| {\n            if key.is_empty() {\n                *byte.borrow()\n            } else {\n                let result = *byte.borrow() ^ key[*position % key.len()];\n                *position += 1;\n                result\n            }\n        })\n    }"}},
    {"name": "edit", "arguments": {"path": "src/lib.rs", "after": "38wi", "new": "\n\n#[cfg(feature = \"io\")]\nimpl<'a> Xorcism<'a> {\n    pub fn reader<R: std::io::Read>(self, inner: R) -> impl std::io::Read {\n        XorReader { inner, xorcism: self }\n    }\n\n    pub fn writer<W: std::io::Write>(self, inner: W) -> impl std::io::Write {\n        XorWriter { inner, xorcism: self }\n    }\n}\n\n#[cfg(feature = \"io\")]\nstruct XorReader<'a, R> {\n    inner: R,\n    xorcism: Xorcism<'a>,\n}\n\n#[cfg(feature = \"io\")]\nimpl<R: std::io::Read> std::io::Read for XorReader<'_, R> {\n    fn read(&mut self, buffer: &mut [u8]) -> std::io::Result<usize> {\n        let count = std::io::Read::read(&mut self.inner, buffer)?;\n        self.xorcism.munge_in_place(&mut buffer[..count]);\n        Ok(count)\n    }\n}\n\n#[cfg(feature = \"io\")]\nstruct XorWriter<'a, W> {\n    inner: W,\n    xorcism: Xorcism<'a>,\n}\n\n#[cfg(feature = \"io\")]\nimpl<W: std::io::Write> std::io::Write for XorWriter<'_, W> {\n    fn write(&mut self, buffer: &[u8]) -> std::io::Result<usize> {\n        if self.xorcism.key.is_empty() {\n            return std::io::Write::write(&mut self.inner, buffer);\n        }\n        let key_len = self.xorcism.key.len();\n        let transformed: Vec<u8> = buffer.iter().enumerate()\n            .map(|(offset, byte)| *byte ^ self.xorcism.key[(self.xorcism.position + offset) % key_len])\n            .collect();\n        let count = std::io::Write::write(&mut self.inner, &transformed)?;\n        self.xorcism.position += count;\n        Ok(count)\n    }\n\n    fn flush(&mut self) -> std::io::Result<()> {\n        std::io::Write::flush(&mut self.inner)\n    }\n}\n"}},
